SELECT 1 AS ARQ, A.PRODUTO, A.COR_PRODUTO, A.CODIGO_BARRA, B.DESC_PRODUTO, DESC_COR_PRODUTO, 0 AS QTD, preco1 AS CUSTO 
FROM PRODUTOS_BARRA A
INNER JOIN PRODUTOS B 
	ON B.PRODUTO = A.PRODUTO
INNER JOIN PRODUTOS_PRECOS c
	ON c.PRODUTO = b.PRODUTO and c.CODIGO_TAB_PRECO = '02'
INNER JOIN PRODUTO_CORES D
	ON D.PRODUTO = A.PRODUTO and D.COR_PRODUTO = A.COR_PRODUTO
